    26	    }
    27	
    28	    @Override
    29	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    30	        if (companyCode == null || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
    31	            throw new InvalidRequestException("Código de empresa inválido");
    32	        }
    33	        this.companyCode = companyCode;
    34	    }
    35	
    36	    @Override
    37	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    38	        BigDecimal subtotal = BigDecimal.ZERO;
    39	        LocalDate current = checkIn;
    40	
    41	        while (current.isBefore(checkOut)) {
    42	            BigDecimal nightRate = room.getNightlyRate();
    43	
    44	            if (DateUtil.isHighSeason(current)) {
    45	                nightRate = MoneyUtil.round(nightRate.multiply(new BigDecimal("1.20")));
    46	            }
    47	
    48	            subtotal = subtotal.add(nightRate);
    49	            current = current.plusDays(1);
    50	        }
    51	
    52	        return MoneyUtil.round(subtotal);
    53	    }
    54	
    55	    @Override
    56	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
    57	        BigDecimal discountRate = COMPANY_DISCOUNTS.get(companyCode);
    58	        return MoneyUtil.round(subtotal.multiply(discountRate));
    59	    }
    60	
