     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.*;
    13	
    14	public class ReservationService {
    15	    private final RoomService roomService;
    16	    private final MessageService messageService;
    17	    private final Map<Long, Reservation> reservations = new HashMap<>();
    18	    private long nextId = 1;
    19	
    20	    public ReservationService(RoomService roomService, MessageService messageService) {
    21	        this.roomService = roomService;
    22	        this.messageService = messageService;
    23	    }
    24	
    25	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
    26	                                          LocalDate checkIn, LocalDate checkOut, int guests,
    27	                                          RatePlanType ratePlanType, String companyCode) {
    28	        Room room = roomService.getRoom(roomNumber);
    29	
    30	        if (guests < 1) {
    31	            throw new InvalidRequestException("Número de hóspedes deve ser no mínimo 1");
    32	        }
    33	
    34	        if (guests > room.getCapacity()) {
    35	            throw new CapacityExceededException();
    36	        }
    37	
    38	        if (!checkIn.isBefore(checkOut)) {
    39	            throw new InvalidRequestException("Data de saída deve ser após a data de entrada");
    40	        }
    41	
    42	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
    43	        ratePlan.validate(room, checkIn, checkOut, guests, companyCode);
    44	
    45	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    46	            throw new RoomUnavailableException();
    47	        }
    48	
    49	        BigDecimal subtotal = ratePlan.calculateSubtotal(room, checkIn, checkOut);
    50	        BigDecimal discount = ratePlan.calculateDiscount(subtotal);
    51	        BigDecimal total = MoneyUtil.round(subtotal.subtract(discount));
    52	
    53	        Reservation reservation = new Reservation(
    54	            nextId++, roomNumber, guestName, guestEmail, guestCpf,
    55	            checkIn, checkOut, guests, ratePlanType, subtotal, discount, total
    56	        );
    57	
    58	        reservations.put(reservation.getId(), reservation);
    59	        return reservation;
    60	    }
    61	
    62	    public Reservation getReservation(long id) {
    63	        Reservation reservation = reservations.get(id);
    64	        if (reservation == null) {
    65	            throw new ReservationNotFoundException();
    66	        }
    67	        return reservation;
    68	    }
    69	
    70	    public Reservation confirmReservation(long id) {
    71	        Reservation reservation = getReservation(id);
    72	
    73	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    74	            throw new OperationNotAllowedException("Apenas reservas pendentes podem ser confirmadas");
    75	        }
    76	
    77	        reservation.setStatus(ReservationStatus.CONFIRMED);
    78	        reservation.setAmountPaid(reservation.getTotal());
    79	
    80	        sendConfirmationEmail(reservation);
    81	
    82	        return reservation;
    83	    }
    84	
    85	    public Reservation cancelReservation(long id) {
    86	        Reservation reservation = getReservation(id);
    87	
    88	        if (reservation.getStatus() != ReservationStatus.PENDING &&
    89	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
    90	            throw new OperationNotAllowedException("Apenas reservas pendentes ou confirmadas podem ser canceladas");
    91	        }
    92	
    93	        RatePlan ratePlan = RatePlanFactory.create(reservation.getRatePlan());
    94	        BigDecimal refund = ratePlan.calculateRefund(reservation.getAmountPaid());
    95	
    96	        reservation.setStatus(ReservationStatus.CANCELLED);
    97	        reservation.setRefund(refund);
    98	
    99	        return reservation;
   100	    }
   101	
   102	    public Reservation checkIn(long id) {
   103	        Reservation reservation = getReservation(id);
   104	
   105	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   106	            throw new OperationNotAllowedException("Apenas reservas confirmadas podem fazer check-in");
   107	        }
   108	
   109	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   110	        return reservation;
   111	    }
   112	
   113	    public Reservation checkOut(long id) {
   114	        Reservation reservation = getReservation(id);
   115	
   116	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   117	            throw new OperationNotAllowedException("Apenas reservas com check-in podem fazer check-out");
   118	        }
   119	
   120	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   121	        return reservation;
   122	    }
   123	
   124	    public List<Reservation> getAllReservations() {
   125	        return new ArrayList<>(reservations.values());
   126	    }
   127	
   128	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   129	        return reservations.values().stream()
   130	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   131	            .filter(r -> !r.isCancelled())
   132	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   133	    }
   134	
   135	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   136	        return start1.isBefore(end2) && start2.isBefore(end1);
   137	    }
   138	
   139	    private void sendConfirmationEmail(Reservation reservation) {
   140	        String subject = "Reserva confirmada - Pousada Maré Alta";
   141	        String document = generateDocumentText(reservation);
   142	
   143	        String body = String.format(
   144	            "Olá, %s!\n\n" +
   145	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   146	            "%s\n\n" +
   147	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   148	            "Até breve!",
   149	            reservation.getGuestName(),
   150	            document
   151	        );
   152	
   153	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
   154	    }
   155	
   156	    public String generateDocumentText(Reservation reservation) {
   157	        if (!reservation.isPaid()) {
   158	            throw new OperationNotAllowedException("Comprovante disponível apenas para reservas pagas");
   159	        }
   160	
   161	        Room room = roomService.getRoom(reservation.getRoomNumber());
   162	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   163	
   164	        StringBuilder doc = new StringBuilder();
   165	        doc.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
   166	        doc.append(String.format("Hóspede: %s (CPF %s)%n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
   167	        doc.append(String.format("Quarto: %s (%s)%n", reservation.getRoomNumber(), room.getType()));
   168	        doc.append(String.format("Entrada: %s | Saída: %s | %d %s%n",
   169	            reservation.getCheckIn().format(dateFormatter),
   170	            reservation.getCheckOut().format(dateFormatter),
   171	            reservation.getNights(),
   172	            reservation.getNights() == 1 ? "diária" : "diárias"));
   173	        doc.append(String.format("Diárias: %s%n", formatMoney(reservation.getSubtotal())));
   174	
   175	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   176	            doc.append(String.format("Desconto: %s%n", formatMoney(reservation.getDiscount())));
   177	        }
   178	
   179	        doc.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
   180	
   181	        return doc.toString();
   182	    }
   183	
   184	    private String formatCpf(String cpf) {
   185	        if (cpf.length() == 11) {
   186	            return String.format("%s.%s.%s-%s",
   187	                cpf.substring(0, 3),
   188	                cpf.substring(3, 6),
   189	                cpf.substring(6, 9),
   190	                cpf.substring(9, 11));
   191	        }
   192	        return cpf;
   193	    }
   194	
   195	    private String formatMoney(BigDecimal value) {
   196	        return String.format("R$ %,.2f", value).replace(",", "X").replace(".", ",").replace("X", ".");
   197	    }
   198	}
