     9	    public static boolean isHighSeason(LocalDate date) {
    10	        Month month = date.getMonth();
    11	        int day = date.getDayOfMonth();
    12	
    13	        if (month == Month.JULY) {
    14	            return true;
    15	        }
    16	
    17	        if (month == Month.DECEMBER && day >= 15) {
    18	            return true;
    19	        }
    20	
    21	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    22	            return true;
    23	        }
    24	
    25	        return false;
    26	    }
    27	
    28	    public static boolean isFriday(LocalDate date) {
    29	        return date.getDayOfWeek() == DayOfWeek.FRIDAY;
    30	    }
    31	
    32	    public static boolean isSunday(LocalDate date) {
    33	        return date.getDayOfWeek() == DayOfWeek.SUNDAY;
    34	    }
    35	}
