   251	    public String generateOccupancyReport(LocalDate date) {
   252	        List<Reservation> occupiedRooms = reservationService.getAllReservations().stream()
   253	            .filter(r -> r.isPaid())
   254	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
   255	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
   256	            .collect(Collectors.toList());
   257	
   258	        StringBuilder csv = new StringBuilder();
   259	        csv.append("room,type,reservation,check_in,check_out\n");
   260	
   261	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
   262	
   263	        for (Reservation reservation : occupiedRooms) {
   264	            csv.append(String.format("%s,%s,%d,%s,%s\n",
   265	                reservation.getRoomNumber(),
   266	                roomService.getRoom(reservation.getRoomNumber()).getType(),
   267	                reservation.getId(),
   268	                reservation.getCheckIn().format(formatter),
   269	                reservation.getCheckOut().format(formatter)
   270	            ));
   271	        }
   272	
   273	        csv.append(String.format("total,%d/%d\n", occupiedRooms.size(), roomService.getTotalRooms()));
   274	
   275	        return csv.toString();
   276	    }
   277	
   278	    public String generateRevenueReport(YearMonth month) {
   279	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
   280	            .filter(r -> {
   281	                YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
   282	                return checkInMonth.equals(month);
   283	            })
   284	            .filter(r -> {
   285	                BigDecimal revenue = r.getAmountPaid();
   286	                if (r.getRefund() != null) {
   287	                    revenue = revenue.subtract(r.getRefund());
   288	                }
   289	                return revenue.compareTo(BigDecimal.ZERO) > 0;
   290	            })
   291	            .sorted(Comparator.comparing(Reservation::getCheckIn)
   292	                .thenComparing(Reservation::getId))
   293	            .collect(Collectors.toList());
   294	
   295	        StringBuilder csv = new StringBuilder();
   296	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   297	
   298	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
   299	        BigDecimal total = BigDecimal.ZERO;
   300	
   301	        for (Reservation reservation : monthReservations) {
   302	            BigDecimal amount = reservation.getAmountPaid();
   303	            if (reservation.getRefund() != null) {
   304	                amount = amount.subtract(reservation.getRefund());
   305	            }
   306	
   307	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
   308	                reservation.getId(),
   309	                reservation.getRoomNumber(),
   310	                reservation.getCheckIn().format(formatter),
   311	                reservation.getCheckOut().format(formatter),
   312	                reservation.getStatus(),
   313	                formatAmount(amount)
   314	            ));
   315	
   316	            total = total.add(amount);
   317	        }
   318	
   319	        csv.append(String.format("total,%s\n", formatAmount(total)));
   320	
   321	        return csv.toString();
   322	    }
